import crypto from "node:crypto";
import { normalizeAuthIdentity, consumeAuthAttempt } from "../../../lib/authRateLimit";
import { mailDeliveryEnabled, passwordResetUrl, sendPasswordResetEmail } from "../lib/mail";
import { guardKeystonePrismaResults } from "../lib/prisma-result";
import { lockTransactionKey } from "./classCapacity";
import { roleCapabilityFields } from "../models/roleCapabilities";

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const LINK_MINUTES = 60;

type Delivery = "email" | "inPerson";

async function peopleActor(context: any) {
  const session = context.session as any;
  const organizationId = session?.data?.organization?.id;
  if (!session?.itemId || !organizationId) throw new Error("Organization session required");
  // Current capabilities, not the stateless-session snapshot.
  const user = await context.sudo().query.User.findOne({ where: { id: session.itemId }, query: "id organization { id } role { canAccessDashboard canManagePeople canManageAllRecords organization { id } }" });
  if (!user || user.organization?.id !== organizationId || user.role?.organization?.id !== organizationId) throw new Error("Actor organization mismatch");
  if (!user.role?.canAccessDashboard || !user.role?.canManagePeople) throw new Error("People management permission required");
  return { userId: session.itemId as string, organizationId: organizationId as string, canManageAllRecords: Boolean(user.role.canManageAllRecords) };
}

function parseDelivery(value: unknown): Delivery {
  if (value === "email" || value === "inPerson") return value;
  return mailDeliveryEnabled() ? "email" : "inPerson";
}

/**
 * Issues a one-use, expiring password link for an existing account. Staff never learn or choose
 * the password: the link goes to the account's own email, or — when mail is off — it is shown
 * once for an in-person handoff after staff verify identity. Every issue is recorded.
 */
async function issueAccessLink(context: any, input: {
  actor: { userId: string; organizationId: string };
  user: { id: string; email: string };
  audience: "dashboard" | "storefront";
  delivery: Delivery;
  memberId?: string | null;
  purpose: string;
}) {
  const prisma = guardKeystonePrismaResults(context.prisma as any);
  if (!(await consumeAuthAttempt(context.prisma, `access-link:${input.user.id}`, 5, 60 * 60 * 1000))) {
    throw new Error("Too many links were issued for this account in the last hour; try again later");
  }
  if (input.delivery === "email" && !mailDeliveryEnabled()) throw new Error("Email delivery is turned off; issue the link for an in-person handoff instead");
  const token = crypto.randomBytes(24).toString("base64url");
  const issuedAt = new Date();
  await context.sudo().db.User.updateOne({ where: { id: input.user.id }, data: { passwordResetToken: token, passwordResetIssuedAt: issuedAt, passwordResetRedeemedAt: null } });
  if (input.memberId) {
    await prisma.operationalNotice.create({ data: {
      organizationId: input.actor.organizationId, memberId: input.memberId, key: crypto.createHash("sha256").update(`${input.actor.organizationId}:access-link:${input.user.id}:${issuedAt.toISOString()}`).digest("hex"),
      kind: "account", status: "pending",
      message: "Staff issued a one-use password link for your account. If you did not ask for it, contact the club.",
      history: [{ at: issuedAt.toISOString(), userId: input.actor.userId, action: `issued-${input.purpose}-link`, delivery: input.delivery }],
    } });
  }
  const expiresAt = new Date(issuedAt.getTime() + LINK_MINUTES * 60_000).toISOString();
  if (input.delivery === "email") {
    try {
      await sendPasswordResetEmail(token, input.user.email, input.audience);
    } catch {
      return { delivered: "failed" as const, email: input.user.email, url: null, expiresAt };
    }
    return { delivered: "email" as const, email: input.user.email, url: null, expiresAt };
  }
  return { delivered: "inPerson" as const, email: input.user.email, url: passwordResetUrl(token, input.user.email, input.audience), expiresAt };
}

/** Front-desk recovery for a same-tenant member account (B-008): never an arbitrary password. */
export async function issueMemberAccessLink(_root: unknown, { memberId, delivery }: { memberId: string; delivery?: string }, context: any) {
  const actor = await peopleActor(context);
  const prisma = guardKeystonePrismaResults(context.prisma as any);
  const member = await prisma.member.findFirst({ where: { id: memberId, organizationId: actor.organizationId }, select: { id: true, userId: true, status: true } });
  if (!member?.userId) throw new Error("This member has no account yet; send an invitation instead");
  if (member.status === "cancelled") throw new Error("Closed member accounts can't be recovered");
  if (member.userId === actor.userId) throw new Error("Use Reset password for your own account");
  const user = await prisma.user.findFirst({ where: { id: member.userId, organizationId: actor.organizationId }, select: { id: true, email: true, role: { select: Object.fromEntries(roleCapabilityFields.map((field) => [field, true])) } } });
  if (!user?.email) throw new Error("Member account not found");
  // Staff accounts are recovered by a global administrator, never by a peer.
  const staffCapabilities = user.role ? roleCapabilityFields.filter((field) => (user.role as any)[field]) : [];
  if (staffCapabilities.length && !actor.canManageAllRecords) throw new Error("This account has staff access; an administrator must recover it");
  return issueAccessLink(context, { actor, user, audience: staffCapabilities.includes("canAccessDashboard") ? "dashboard" : "storefront", delivery: parseDelivery(delivery), memberId: member.id, purpose: "recovery" });
}

/**
 * First claim of an onboarding placeholder coach account (C-013/A-011): only an account the
 * onboarding run recorded as a placeholder, still unclaimed and still on the bounded instructor
 * role, may receive the real coach's email; then a one-use setup link is issued for it.
 */
export async function prepareInstructorAccount(
  _root: unknown,
  { instructorId, email, delivery }: { instructorId: string; email: string; delivery?: string },
  context: any,
) {
  const actor = await peopleActor(context);
  const normalizedEmail = normalizeAuthIdentity(email);
  if (!emailPattern.test(normalizedEmail) || normalizedEmail.length > 254 || normalizedEmail.endsWith(".invalid")) {
    throw new Error("Enter the coach's real email address");
  }
  const prisma = guardKeystonePrismaResults(context.prisma as any);
  const claimed = await prisma.$transaction(async (tx: any) => {
    await lockTransactionKey(tx, `instructor-claim:${actor.organizationId}:${instructorId}`);
    const instructor = await tx.instructor.findFirst({ where: { id: instructorId, organizationId: actor.organizationId }, select: { id: true, userId: true } });
    if (!instructor?.userId) throw new Error("Instructor account was not found in this organization");
    const run = await tx.onboardingRun.findUnique({ where: { organizationId: actor.organizationId }, select: { id: true, manifest: true } });
    const placeholders = (run?.manifest as any)?.placeholderUsers || {};
    const provenance = placeholders[instructor.userId];
    if (!provenance) throw new Error("Only coach accounts created as onboarding placeholders can be claimed here; existing coaches manage their own sign-in");
    const user = await tx.user.findFirst({ where: { id: instructor.userId, organizationId: actor.organizationId }, select: { id: true, email: true, passwordResetRedeemedAt: true, role: { select: Object.fromEntries(roleCapabilityFields.map((field) => [field, true])) } } });
    if (!user) throw new Error("Instructor account was not found in this organization");
    if (user.passwordResetRedeemedAt || provenance.claimedAt) throw new Error("This coach has already claimed the account; they manage their own email and password");
    const extra = roleCapabilityFields.filter((field) => field !== "canAccessDashboard" && field !== "isInstructor" && (user.role as any)?.[field]);
    if (!user.role?.isInstructor || extra.length) throw new Error("This account no longer has the bounded instructor role; an administrator must handle it");
    if (user.email !== provenance.seedEmail && user.email !== provenance.claimEmail) throw new Error("This account's email was changed outside the claim workflow; an administrator must review it");
    const owner = await tx.user.findFirst({ where: { email: normalizedEmail }, select: { id: true } });
    if (owner && owner.id !== user.id) throw new Error("Another account already uses that email");
    await tx.user.update({ where: { id: user.id }, data: { email: normalizedEmail } });
    await tx.onboardingRun.update({ where: { id: run!.id }, data: { manifest: { ...(run!.manifest as any), placeholderUsers: { ...placeholders, [user.id]: { ...provenance, claimEmail: normalizedEmail, claimIssuedAt: new Date().toISOString(), claimIssuedBy: actor.userId } } } } });
    return { id: user.id, email: normalizedEmail };
  });
  const issued = await issueAccessLink(context, { actor, user: claimed, audience: "dashboard", delivery: parseDelivery(delivery), memberId: null, purpose: "claim" });
  return { userId: claimed.id, ...issued };
}

/** Onboarding placeholder coach accounts and their claim state, for staff who manage people. */
export async function instructorClaimQueue(_root: unknown, _args: unknown, context: any) {
  const actor = await peopleActor(context);
  const prisma = guardKeystonePrismaResults(context.prisma as any);
  const run = await prisma.onboardingRun.findUnique({ where: { organizationId: actor.organizationId }, select: { manifest: true } });
  const placeholders = ((run?.manifest as any)?.placeholderUsers || {}) as Record<string, any>;
  const userIds = Object.keys(placeholders).slice(0, 200);
  if (!userIds.length) return [];
  const instructors = await prisma.instructor.findMany({
    where: { organizationId: actor.organizationId, userId: { in: userIds } },
    select: { id: true, isActive: true, userId: true, user: { select: { name: true, email: true, passwordResetRedeemedAt: true } } },
    orderBy: [{ id: "asc" }],
  });
  return instructors.map((row: any) => {
    const provenance = placeholders[row.userId] || {};
    const claimed = Boolean(row.user?.passwordResetRedeemedAt || provenance.claimedAt);
    return {
      instructorId: row.id,
      name: row.user?.name || "Coach",
      isActive: row.isActive,
      email: claimed || provenance.claimEmail ? row.user?.email || "" : "",
      status: claimed ? "claimed" : provenance.claimIssuedAt ? "link_issued" : "unclaimed",
      claimIssuedAt: provenance.claimIssuedAt || null,
    };
  });
}
